// Splits a bill (in agorot, a whole number) between people by weights.
function toExactRational(num) {
  // Convert a positive JS float to an exact rational { num: BigInt, exp: number }
  // representing num * 10^(-exp), using its shortest accurate decimal representation
  // (via toString()) so e.g. 0.1 and 0.2 are exact decimals, while also supporting
  // scientific notation.
  const s = num.toString().toLowerCase();
  const [mantissa, expPart] = s.split("e");
  const sciExp = expPart ? parseInt(expPart, 10) : 0;
  const dotIdx = mantissa.indexOf(".");
  let digits;
  let fracLen;
  if (dotIdx === -1) {
    digits = mantissa;
    fracLen = 0;
  } else {
    digits = mantissa.slice(0, dotIdx) + mantissa.slice(dotIdx + 1);
    fracLen = mantissa.length - dotIdx - 1;
  }
  return { digits: BigInt(digits), scale: fracLen - sciExp };
}

function splitBill(total, weights) {
  if (!Number.isInteger(total) || total < 0) throw new Error("bad total");
  if (!Array.isArray(weights) || !weights.length || weights.some((w) => !(w > 0) || !Number.isFinite(w))) {
    throw new Error("bad weights");
  }

  // Convert weights to exact integers by scaling by a common power of 10.
  const parsed = weights.map(toExactRational);
  const maxScale = parsed.reduce((m, p) => (p.scale > m ? p.scale : m), 0);
  const bigWeights = parsed.map((p) => {
    const diff = maxScale - p.scale;
    return p.digits * 10n ** BigInt(diff);
  });

  const sum = bigWeights.reduce((a, b) => a + b, 0n);
  const bigTotal = BigInt(total);

  const floors = [];
  const remainders = [];
  let floorSum = 0n;

  for (let i = 0; i < bigWeights.length; i++) {
    const numer = bigTotal * bigWeights[i];
    const q = numer / sum;
    const r = numer % sum;
    floors.push(Number(q));
    remainders.push({ index: i, rem: r });
    floorSum += q;
  }

  const leftover = Number(bigTotal - floorSum);

  remainders.sort((a, b) => {
    if (b.rem !== a.rem) return b.rem > a.rem ? 1 : -1;
    return a.index - b.index;
  });

  for (let i = 0; i < leftover; i++) {
    floors[remainders[i].index] += 1;
  }

  return floors;
}

module.exports = { splitBill };
