// Splits a bill (in agorot, a whole number) between people by weights.
function toExactIntWeights(weights) {
  let maxDecimals = 0;
  const parsed = weights.map((w) => {
    const s = w.toString().toLowerCase();
    const [mantissa, expStr] = s.split("e");
    const exp = expStr ? parseInt(expStr, 10) : 0;
    const [intPart, fracPart = ""] = mantissa.split(".");
    const decimals = Math.max(0, fracPart.length - exp);
    if (decimals > maxDecimals) maxDecimals = decimals;
    return { digits: intPart + fracPart, exp, fracLen: fracPart.length };
  });

  return parsed.map(({ digits, exp, fracLen }) => {
    const shift = maxDecimals + exp - fracLen;
    return BigInt(digits) * 10n ** BigInt(shift);
  });
}

function splitBill(total, weights) {
  if (!Number.isInteger(total) || total < 0) throw new Error("bad total");
  if (!Array.isArray(weights) || !weights.length || weights.some((w) => typeof w !== "number" || !Number.isFinite(w) || !(w > 0))) {
    throw new Error("bad weights");
  }

  const bigTotal = BigInt(total);
  const bigWeights = toExactIntWeights(weights);
  const sum = bigWeights.reduce((a, b) => a + b, 0n);

  const floors = [];
  const remainders = [];
  let currentSum = 0n;

  for (let i = 0; i < bigWeights.length; i++) {
    const prod = bigTotal * bigWeights[i];
    const fl = prod / sum;
    const rem = prod % sum;
    floors.push(Number(fl));
    remainders.push({ index: i, rem });
    currentSum += fl;
  }

  let leftover = Number(bigTotal - currentSum);

  remainders.sort((a, b) => {
    if (b.rem !== a.rem) return b.rem > a.rem ? 1 : -1;
    return a.index - b.index;
  });

  for (let i = 0; i < leftover; i++) {
    floors[remainders[i].index] += 1;
  }

  return floors;
}

module.exports = { splitBill };
