const { parseTime, parseRange, formatMinutes } = require("./time-range");

function freeSlots(busy, dayStart, dayEnd, minLen) {
  const start = parseTime(dayStart);
  const end = parseTime(dayEnd);
  if (end <= start) {
    throw new Error("dayEnd must be after dayStart: " + dayStart + "-" + dayEnd);
  }

  const min = Number(minLen);
  const intervals = [];
  for (const s of busy) {
    const r = parseRange(s);
    const clampedStart = Math.max(start, r.start);
    const clampedEnd = Math.min(end, r.end);
    if (clampedEnd > clampedStart) {
      intervals.push({ start: clampedStart, end: clampedEnd });
    }
  }

  intervals.sort((a, b) => a.start - b.start || a.end - b.end);

  const merged = [];
  for (const cur of intervals) {
    if (merged.length === 0 || cur.start > merged[merged.length - 1].end) {
      merged.push({ start: cur.start, end: cur.end });
    } else {
      merged[merged.length - 1].end = Math.max(merged[merged.length - 1].end, cur.end);
    }
  }

  const gaps = [];
  let cursor = start;
  for (const b of merged) {
    if (b.start - cursor >= min && b.start > cursor) {
      gaps.push(`${formatMinutes(cursor)}-${formatMinutes(b.start)}`);
    }
    cursor = Math.max(cursor, b.end);
  }
  if (end - cursor >= min && end > cursor) {
    gaps.push(`${formatMinutes(cursor)}-${formatMinutes(end)}`);
  }

  return gaps;
}

module.exports = { freeSlots };
